async function scenarioForm(id,suggestion=null){
  const cat=await api(p('/catalog'));
  if(cat.components.length<2){toast('Add at least two reviewed packaging components first.');return;}
  const old=id?await api(p('/scenarios/'+id)):null;
  const base=old?.baseline_id??suggestion?.baseline??cat.components.find(x=>x.code==='BOT-104')?.id??cat.components[0].id;
  const candidate=old?.candidate_id??suggestion?.candidate??cat.components.find(x=>x.code==='BOT-209')?.id??cat.components[1].id;
  const inputs=old?JSON.parse(old.inputs):{annual_units:cat.products.reduce((n,pr)=>n+pr.bom.filter(b=>b.component_id===base).reduce((q,b)=>q+pr.annual_units*b.quantity,0),0)||1,extra_per_unit:0,transition_cost:0,assumption_note:''};
  const options=selected=>cat.components.map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(c.code)} · ${esc(c.name)} · ${esc(c.revision)}</option>`).join('');
  showModal(old?'Revise decision scenario':'Create a decision scenario',`<form data-form="scenario" data-id="${esc(id??'')}">${errorBox}<div class="form-grid"><label class="full">Scenario name<input name="name" required minlength="2" value="${esc(old?.name??'')}"></label><label>Approved baseline<select name="baseline_id">${options(base)}</select></label><label>Candidate replacement<select name="candidate_id">${options(candidate)}</select></label><label>Annual component demand · units<input name="annual_units" type="number" min="0.000001" step="any" required value="${inputs.annual_units}"></label><label>Extra logistics / operating cost per component<input name="extra_per_unit" type="number" min="0" step="any" required value="${inputs.extra_per_unit}"></label><label>One-time transition cost<input name="transition_cost" type="number" min="0" step="any" required value="${inputs.transition_cost}"></label><label class="full">Assumptions, price validity & qualification scope<textarea name="assumption_note" required minlength="5" placeholder="Specify price dates, delivery basis, affected SKUs, plant, formula, forecast source and any excluded costs.">${esc(inputs.assumption_note)}</textarea></label></div><p class="small-text muted">The engine checks material, capacity, neck/interface, currency and reviewed source status. Scenario revisions invalidate all qualifications and approval.</p>${submit(old?'Save new revision':'Create scenario')}</form>`);
}
async function openScenario(id){
  const s=await api(p('/scenarios/'+id));S.data.scenario=s;S.view='scenarios';activeNav();
  const e=s.status==='implemented' && s.approved_evaluation?s.approved_evaluation:s.evaluation,f=e.financials;
  const realised=await api(p('/scenarios/'+id+'/benefits'));
  $('#page').innerHTML=head('Decision record · version '+s.version,s.name,`${e.baseline.code} ${e.baseline.revision} → ${e.candidate.code} ${e.candidate.revision}`,`${button('All scenarios','nav','data-view="scenarios"')}${!['change_requested','implemented'].includes(s.status)?button('Revise assumptions','edit-scenario',`data-id="${id}"`):''}<a class="button" href="/api${p('/scenarios/'+id+'/export')}">Export evidence pack</a>`)+
    `<div class="status-line"><div class="actions">${badge(s.status)}${e.approval_current?badge('approved'):''}</div><span class="small-text muted">Scope fingerprint <code>${e.fingerprint.slice(0,14)}</code></span></div><div class="metrics">${metric('Gross annual estimate',f.currency+' '+num(f.gross_annual),'Baseline price − candidate price × demand')}${metric('First-year net estimate',f.currency+' '+num(f.first_year_net),'After extra operating and transition costs')}${metric('Recurring annual estimate',f.currency+' '+num(f.recurring_annual_net),'After annual extra operating costs')}${metric('Material difference',num(f.material_tonnes)+' t','Mass only · not a carbon claim')}</div><div class="split"><section class="card"><h2>1. Attribute screen</h2>${table(['Attribute','Baseline','Candidate','Result'],e.checks.map(c=>`<tr><td>${esc(c.attribute.replaceAll('_',' '))}</td><td>${esc(c.baseline)}</td><td>${esc(c.candidate)}</td><td class="${c.passed?'check':'fail'}">${c.passed?'Pass':'Blocked'}</td></tr>`))}<h3 class="subheading">Assumptions & scope</h3><p class="small-text">${esc(e.assumptions.assumption_note)}</p><p class="small-text muted">Annual demand entered: ${num(f.annual_units)} · Current linked BOM forecast: ${num(e.annual_component_demand)}<br>Annual extra cost: ${f.currency} ${num(f.annual_extra)} · Transition: ${f.currency} ${num(f.transition)}</p></section><section class="card"><h2>2. Qualification evidence</h2><p class="small-text muted">Reviewer records must apply to this exact scope and current component revisions.</p>${Object.entries(e.qualifications).map(([key,q])=>`<div class="source"><div class="status-line"><strong>${esc(key.replaceAll('_',' '))}</strong>${q.valid?badge('approved'):badge('review')}</div>${q.record?`<p class="small-text">${esc(q.record.note)}</p><span class="small-text muted">${date(q.record.at)} · Reviewer #${q.record.by}</span> ${button('Evidence','document',`data-id="${esc(q.record.evidence_id)}"`,'small')}`:'<p class="small-text muted">No current qualification record.</p>'}${['draft','qualified'].includes(s.status)?`<div class="actions">${button(q.record?'Update record':'Record result','qualification',`data-id="${id}" data-key="${key}" ${e.eligible?'':'disabled'}`,'small')}</div>`:''}</div>`).join('')}</section></div><section class="card top-space"><h2>3. Approval & rollout</h2><div class="actions">${['draft','qualified'].includes(s.status)?button('Approve decision','approve',`data-id="${id}" ${e.can_approve?'':'disabled'}`,'primary'):''}${s.status==='approved'?button('Request controlled change','request-change',`data-id="${id}" ${e.approval_current?'':'disabled'}`,'primary'):''}${s.status==='change_requested'?`${button('Deliver change event','deliver',`data-id="${id}" ${e.approval_current?'':'disabled'}`)}${button('Acknowledge implementation','implement',`data-id="${id}" ${e.approval_current?'':'disabled'}`,'primary')}`:''}${s.status==='implemented'?'<span class="check">Implementation acknowledgement recorded</span>':''}</div><p class="small-text muted">${s.approved_at?'Decision approved '+date(s.approved_at)+' by reviewer #'+s.approved_by+'. ':''}Exports and outbound delivery do not imply ERP implementation. Implementation requires a separate receipt and reviewer acknowledgement.</p>${s.implementation?`<pre>${esc(JSON.stringify(JSON.parse(s.implementation),null,2))}</pre>`:''}</section><section class="card"><div class="status-line"><h2>Realised benefit records</h2>${s.status==='implemented'?button('Record actuals','record-benefit',`data-id="${id}"`,'small'):''}</div><p class="small-text muted">Separate from scenario estimates. Enter completed periods and reviewed actual cost evidence; overlapping periods are blocked.</p>${realised.length?table(['Period','Actual units','Net benefit','Evidence'],realised.map(r=>`<tr><td>${esc(r.period_start)} to ${esc(r.period_end)}</td><td>${num(r.actual_units)}</td><td>${esc(f.currency)} ${num(r.realised_net)}</td><td>${button('Source','document',`data-id="${r.evidence_id}"`,'small')}</td></tr>`)):empty('No realised benefit records.')}</section><section class="card"><h2>Affected finished products</h2>${e.affected_products.length?table(['SKU','Product','Plant / formula','Forecast','BOM quantity'],e.affected_products.map(pr=>`<tr><td>${esc(pr.sku)}</td><td>${esc(pr.name)}</td><td>${esc(pr.plant)} / ${esc(pr.formula)}</td><td>${num(pr.annual_units)}</td><td>${esc(String(pr.quantity))}</td></tr>`)):empty('No linked SKUs. Import a BOM to establish impact scope.')}<ul class="help-list">${e.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`;
}
